"""Stage 1 - read the raw regional feeds and normalise them into records.

Amounts are normalised to MINOR UNITS (cents) as integers, because the feeds
disagree about decimal separators and floats were losing pennies on the EU feed.
"""
import csv


REGION_CODES = {"North America": "na", "EMEA": "emea", "APAC": "apac"}


def _to_minor_units(raw):
    """'1234.50' -> 123450. Accepts comma or dot as the decimal separator."""
    s = str(raw).strip().replace(" ", "")
    # Whichever separator comes last is the decimal one; the other groups digits.
    if s.rfind(",") > s.rfind("."):
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return int(round(float(s) * 100))


def parse_rows(path):
    """Yield one record per feed row.

    record = {"region_code": str, "currency": str, "amount": int (minor units),
              "order_id": str}
    """
    out = []
    with open(path, newline="", encoding="utf-8") as fh:
        for row in csv.DictReader(fh):
            region = row["region"].strip()
            out.append({
                "region_code": REGION_CODES.get(region, region.lower()),
                "currency": row["currency"].strip().upper(),
                "amount": _to_minor_units(row["amount"]),
                "order_id": row["order_id"].strip(),
            })
    return out

"""Stage 2 - convert every record to USD and aggregate per region."""

FX_TO_USD = {
    "USD": 1.0,
    "EUR": 1.09,
    "JPY": 0.0067,
}


def to_usd(record):
    """Convert one record's amount to USD. Returns None if we cannot price it."""
    rate = FX_TO_USD.get(record["currency"])
    if rate is None:
        return None
    return {**record, "amount_usd": record["amount"] * rate}


def aggregate(records):
    """Sum per region. Rows we cannot price are not part of the total."""
    priced = [r for r in (to_usd(rec) for rec in records) if r is not None]
    totals = {}
    for r in priced:
        totals.setdefault(r["region_code"], 0.0)
        totals[r["region_code"]] += r["amount_usd"]
    return [{"region_code": code, "total_usd": total} for code, total in totals.items()]

"""Stage 3 - rank the regions and render the summary."""

DISPLAY = {"na": "North America", "emea": "EMEA", "apac": "APAC"}


def _amount(row):
    # transform used to emit "total"; it emits "total_usd" since the currency
    # work. Accept both so old saved runs still render.
    if "total_usd" in row:
        return row["total_usd"]
    return row.get("total", 0)


def rank(rows):
    """Highest revenue first."""
    return sorted(rows, key=lambda r: r.get("total", 0), reverse=True)


def render(rows):
    ranked = rank(rows)
    lines = ["Regional revenue, highest first", ""]
    for i, r in enumerate(ranked, 1):
        name = DISPLAY.get(r["region_code"], r["region_code"])
        lines.append("%d. %-15s $%.2f" % (i, name, _amount(r)))
    lines.append("")
    lines.append("Top region: %s" % DISPLAY.get(ranked[0]["region_code"], "?"))
    return "\n".join(lines)

import os, sys, tempfile, unittest
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from revenue import extract

CSV = """order_id,region,currency,amount
A-1,North America,USD,1234.50
A-2,EMEA,EUR,"2.000,25"
A-3,APAC,JPY,500000
"""


class ToMinorUnits(unittest.TestCase):
    def test_dot_decimal(self):
        self.assertEqual(extract._to_minor_units("1234.50"), 123450)

    def test_comma_decimal(self):
        self.assertEqual(extract._to_minor_units("2.000,25"), 200025)

    def test_integer(self):
        self.assertEqual(extract._to_minor_units("500000"), 50000000)

    def test_returns_int(self):
        self.assertIsInstance(extract._to_minor_units("9.99"), int)


class ParseRows(unittest.TestCase):
    def setUp(self):
        fd, self.path = tempfile.mkstemp(suffix=".csv")
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(CSV)

    def tearDown(self):
        os.unlink(self.path)

    def test_row_count(self):
        self.assertEqual(len(extract.parse_rows(self.path)), 3)

    def test_region_codes(self):
        codes = [r["region_code"] for r in extract.parse_rows(self.path)]
        self.assertEqual(codes, ["na", "emea", "apac"])

    def test_currency_uppercased(self):
        self.assertEqual(extract.parse_rows(self.path)[1]["currency"], "EUR")

    def test_amounts_are_minor_units(self):
        amounts = [r["amount"] for r in extract.parse_rows(self.path)]
        self.assertEqual(amounts, [123450, 200025, 50000000])


if __name__ == "__main__":
    unittest.main()

import os, sys, unittest
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from revenue import transform


def rec(amount, currency="USD", region="na"):
    return {"region_code": region, "currency": currency,
            "amount": amount, "order_id": "X"}


class ToUsd(unittest.TestCase):
    def test_usd_unchanged(self):
        self.assertEqual(transform.to_usd(rec(100.0))["amount_usd"], 100.0)

    def test_eur_converted(self):
        self.assertAlmostEqual(
            transform.to_usd(rec(100.0, "EUR"))["amount_usd"], 109.0)

    def test_unknown_currency_is_none(self):
        self.assertIsNone(transform.to_usd(rec(100.0, "XYZ")))

    def test_original_fields_kept(self):
        out = transform.to_usd(rec(50.0, "USD", "emea"))
        self.assertEqual(out["region_code"], "emea")
        self.assertEqual(out["order_id"], "X")


class Aggregate(unittest.TestCase):
    def test_sums_within_region(self):
        rows = transform.aggregate([rec(10.0), rec(15.0)])
        self.assertEqual(rows, [{"region_code": "na", "total_usd": 25.0}])

    def test_splits_regions(self):
        rows = transform.aggregate([rec(10.0, "USD", "na"),
                                    rec(20.0, "USD", "emea")])
        totals = {r["region_code"]: r["total_usd"] for r in rows}
        self.assertEqual(totals, {"na": 10.0, "emea": 20.0})

    def test_mixed_currency_region(self):
        rows = transform.aggregate([rec(100.0, "USD"), rec(100.0, "EUR")])
        self.assertAlmostEqual(rows[0]["total_usd"], 209.0)

    def test_empty_input(self):
        self.assertEqual(transform.aggregate([]), [])


if __name__ == "__main__":
    unittest.main()

import os, sys, unittest
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from revenue import report


def row(code, total):
    return {"region_code": code, "total": total}


class Rank(unittest.TestCase):
    def test_highest_first(self):
        out = report.rank([row("na", 10.0), row("emea", 30.0), row("apac", 20.0)])
        self.assertEqual([r["region_code"] for r in out], ["emea", "apac", "na"])

    def test_single_row(self):
        self.assertEqual(len(report.rank([row("na", 1.0)])), 1)

    def test_empty(self):
        self.assertEqual(report.rank([]), [])

    def test_negative_totals_sort_last(self):
        out = report.rank([row("na", -5.0), row("emea", 1.0)])
        self.assertEqual(out[0]["region_code"], "emea")


class Render(unittest.TestCase):
    def test_names_are_displayed(self):
        text = report.render([row("na", 10.0), row("emea", 30.0)])
        self.assertIn("North America", text)
        self.assertIn("EMEA", text)

    def test_top_region_line(self):
        text = report.render([row("na", 10.0), row("emea", 30.0)])
        self.assertIn("Top region: EMEA", text)

    def test_amount_formatting(self):
        text = report.render([row("na", 1234.5)])
        self.assertIn("$1234.50", text)


if __name__ == "__main__":
    unittest.main()

"""Added 2026-03 after the stale-FX incident: the EUR rate went a week out of
date and EMEA was reported 12% low. This suite watches the rate table and the
conversion arithmetic."""
import os, sys, unittest
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from revenue import transform


def rec(amount, currency):
    return {"region_code": "na", "currency": currency,
            "amount": amount, "order_id": "X"}


class RateTable(unittest.TestCase):
    def test_usd_is_identity(self):
        self.assertEqual(transform.FX_TO_USD["USD"], 1.0)

    def test_every_rate_positive(self):
        for cur, rate in transform.FX_TO_USD.items():
            self.assertGreater(rate, 0, cur)

    def test_expected_currencies_present(self):
        self.assertEqual(set(transform.FX_TO_USD), {"USD", "EUR", "JPY"})

    def test_eur_rate_in_plausible_band(self):
        self.assertTrue(0.9 <= transform.FX_TO_USD["EUR"] <= 1.3)

    def test_jpy_rate_in_plausible_band(self):
        self.assertTrue(0.005 <= transform.FX_TO_USD["JPY"] <= 0.010)


class Conversion(unittest.TestCase):
    def test_eur_regression_march_incident(self):
        # 1000 EUR must not come back as the 12%-low 959.20 we shipped in March
        self.assertAlmostEqual(transform.to_usd(rec(1000.0, "EUR"))["amount_usd"],
                               1090.0, places=6)

    def test_jpy_conversion(self):
        self.assertAlmostEqual(transform.to_usd(rec(1000.0, "JPY"))["amount_usd"],
                               6.7, places=6)

    def test_zero_amount(self):
        self.assertEqual(transform.to_usd(rec(0.0, "EUR"))["amount_usd"], 0.0)

    def test_negative_amount_refund(self):
        self.assertAlmostEqual(transform.to_usd(rec(-100.0, "EUR"))["amount_usd"],
                               -109.0, places=6)

    def test_unpriceable_currency_returns_none(self):
        self.assertIsNone(transform.to_usd(rec(100.0, "GBP")))

    def test_conversion_is_linear(self):
        a = transform.to_usd(rec(1.0, "EUR"))["amount_usd"]
        b = transform.to_usd(rec(1000.0, "EUR"))["amount_usd"]
        self.assertAlmostEqual(b, a * 1000, places=6)


if __name__ == "__main__":
    unittest.main()
